using ReeLib;using System.Text.Json;using System.Numerics;
Directory.SetCurrentDirectory("E:/CodexPepo/RE_Research");
float[] Mat(ReeLib.via.mat4 m)=>[m.m00,m.m01,m.m02,m.m03,m.m10,m.m11,m.m12,m.m13,m.m20,m.m21,m.m22,m.m23,m.m30,m.m31,m.m32,m.m33];
var selected=new[]{"01","02","10","21","40","50"};var parts=new List<object>();var stats=new List<object>();
foreach(var file in Directory.GetFiles("reports/model/samples","*.mesh.*",SearchOption.AllDirectories).Concat(Directory.GetFiles("reports/model_extra/samples","*.mesh.*",SearchOption.AllDirectories).Where(p=>!p.Contains("streaming")))){if(!selected.Any(id=>Path.GetFileName(file).StartsWith("ch0100_"+id+"_00")))continue;using var m=new MeshFile(new FileHandler(file));if(!m.Read())throw new Exception("Read failure");var sf=file.Replace("reports/model/samples","reports/model_streaming/samples").Replace("stm\\character","stm\\streaming\\character");if(File.Exists(sf))m.LoadStreamingData(new FileHandler(sf));var bd=m.BoneData!;var deform=bd.DeformBones.Count>0?bd.DeformBones:bd.Bones;var lodIndex=Math.Min(2,m.MeshData!.LODs.Count-1);var primitives=new List<object>();int vertices=0,triangles=0,maxInfluences=0;float maxWeightError=0;foreach(var g in m.MeshData.LODs[lodIndex].MeshGroups)foreach(var sub in g.Submeshes){var material=m.MaterialNames[sub.materialIndex];if(material.Contains("EyeShell")||material.Contains("Eyelash")||material.Contains("Eyebrow")||material.Contains("Beard"))continue;var pos=sub.Positions;var nor=sub.NormalsTangents;var wt=sub.Weights;var positions=new float[pos.Length*3];var normals=new float[pos.Length*3];var joints=new int[pos.Length*8];var weights=new float[pos.Length*8];for(int i=0;i<pos.Length;i++){positions[i*3]=pos[i].X;positions[i*3+1]=pos[i].Y;positions[i*3+2]=pos[i].Z;var n=nor.Length>i?nor[i].Normal:Vector3.UnitY;normals[i*3]=n.X;normals[i*3+1]=n.Y;normals[i*3+2]=n.Z;var w=wt[i];float sum=0;int used=0;for(int k=0;k<Math.Min(w.IndexCount,8);k++){float val=w.GetWeight(k);if(val<=0)continue;int j=w.GetIndex(k);if(j<0||j>=deform.Count)throw new Exception("Invalid joint");joints[i*8+k]=deform[j].index;weights[i*8+k]=val;sum+=val;used++;}if(sum<=0)throw new Exception("Zero weights");maxWeightError=Math.Max(maxWeightError,Math.Abs(sum-1));for(int k=0;k<8;k++)weights[i*8+k]/=sum;maxInfluences=Math.Max(maxInfluences,used);}var indices=Enumerable.Range(0,(int)sub.indicesCount).Select(i=>sub.Buffer.IntegerFaces!=null?(int)sub.IntegerIndices[i]:(int)sub.Indices[i]).ToArray();int vertexCount=pos.Length;if(indices.Any(i=>i<0||i>=vertexCount))throw new Exception("Invalid face");primitives.Add(new{material,positions,normals,joints,weights,indices});vertices+=pos.Length;triangles+=indices.Length/3;}
parts.Add(new{name=Path.GetFileName(file),source=file,lod=lodIndex,bones=bd.Bones.Select(b=>new{name=b.name,parent=(int)b.parentIndex,local=Mat(b.localTransform),inverseBind=Mat(b.inverseGlobalTransform)}).ToArray(),primitives});stats.Add(new{file,lodIndex,vertices,triangles,bones=bd.Bones.Count,maxInfluences,maxWeightError});Console.WriteLine($"{Path.GetFileName(file)} {vertices} verts {triangles} tris {bd.Bones.Count} bones maxWeights={maxInfluences}");}
var json=JsonSerializer.Serialize(new{parts});File.WriteAllText("player/dist/model.js","window.MODEL_DATA="+json+";");File.WriteAllText("reports/model/export_stats.json",JsonSerializer.Serialize(stats,new JsonSerializerOptions{WriteIndented=true}));

